-- Civic Lens migration 6 (phase 2): discussions for the prototype shell.
-- Threads and posts for topics, bodies, groups, places, meetings, and agenda items.
-- Run once after migration-5. Then run seed-shell.sql (generated by tools/build-shell-seed.mjs).

-- Which places each board covers, so posting can check a person's districts.
create table if not exists body_places (
  body_id text not null references bodies(id) on delete cascade,
  place_id text not null references places(id) on delete cascade,
  primary key (body_id, place_id)
);

create table if not exists discussion_threads (
  id uuid primary key,
  scope_kind text not null check (scope_kind in ('topic', 'body', 'group', 'place', 'meeting', 'item')),
  scope_id text not null,
  title text not null check (char_length(trim(title)) between 1 and 200),
  kind text not null check (kind in ('question', 'information', 'opinion')),
  author_id uuid references profiles(id) on delete cascade,
  author_name text not null default '',
  created_at timestamptz not null default now(),
  constraint threads_have_author check (author_id is not null or author_name <> '')
);
create index if not exists threads_scope_idx on discussion_threads (scope_kind, scope_id);

create table if not exists discussion_posts (
  id uuid primary key default gen_random_uuid(),
  thread_id uuid not null references discussion_threads(id) on delete cascade,
  author_id uuid references profiles(id) on delete cascade,
  author_name text not null default '',
  body text not null check (char_length(trim(body)) between 1 and 1000),
  created_at timestamptz not null default now(),
  constraint posts_have_author check (author_id is not null or author_name <> '')
);
create index if not exists posts_thread_idx on discussion_posts (thread_id, created_at);

-- Who may post. Topics: any signed-in person. Everything else: a person whose districts cover that board, place, meeting, or item.
create or replace function shell_can_post(p_kind text, p_id text)
returns boolean language sql stable security definer set search_path = public as $$
  select case
    when p_kind = 'topic' then exists (select 1 from profiles p where p.id = auth.uid())
    when p_kind = 'place' then exists (
      select 1 from profiles p where p.id = auth.uid() and p_id = any (p.place_ids))
    when p_kind in ('body', 'group') then exists (
      select 1 from profiles p join body_places bp on bp.place_id = any (p.place_ids)
      where p.id = auth.uid() and bp.body_id = p_id)
    when p_kind = 'meeting' then exists (
      select 1 from profiles p join meetings m on m.id = p_id
      join body_places bp on bp.body_id = m.body_id and bp.place_id = any (p.place_ids)
      where p.id = auth.uid())
    when p_kind = 'item' then exists (
      select 1 from profiles p join items i on i.id = p_id
      join meetings m on m.id = i.meeting_id
      join body_places bp on bp.body_id = m.body_id and bp.place_id = any (p.place_ids)
      where p.id = auth.uid())
    else false
  end
$$;

alter table body_places enable row level security;
alter table discussion_threads enable row level security;
alter table discussion_posts enable row level security;

drop policy if exists body_places_read on body_places;
create policy body_places_read on body_places for select to authenticated using (true);

drop policy if exists threads_read on discussion_threads;
create policy threads_read on discussion_threads for select to authenticated using (true);
drop policy if exists threads_insert on discussion_threads;
create policy threads_insert on discussion_threads for insert to authenticated with check (
  author_id = auth.uid() and shell_can_post(scope_kind, scope_id));

drop policy if exists posts_read on discussion_posts;
create policy posts_read on discussion_posts for select to authenticated using (true);
drop policy if exists posts_insert on discussion_posts;
create policy posts_insert on discussion_posts for insert to authenticated with check (
  author_id = auth.uid() and exists (
    select 1 from discussion_threads t
    where t.id = thread_id and shell_can_post(t.scope_kind, t.scope_id)));

-- Readable shapes for the shell. Nicknames come from profiles; sample posts keep their stored name.
create or replace view discussion_thread_view as
select t.id, t.scope_kind, t.scope_id, t.title, t.kind, t.created_at,
       coalesce(nullif(p.nickname, ''), t.author_name) as author_name
from discussion_threads t
left join profiles p on p.id = t.author_id;

create or replace view discussion_post_view as
select d.id, d.thread_id, d.body, d.created_at,
       coalesce(nullif(p.nickname, ''), d.author_name) as author_name
from discussion_posts d
left join profiles p on p.id = d.author_id;

revoke all on body_places, discussion_threads, discussion_posts from anon, authenticated;
grant select on body_places to authenticated;
grant select, insert on discussion_threads, discussion_posts to authenticated;
grant select on discussion_thread_view, discussion_post_view to authenticated;
revoke all on discussion_thread_view, discussion_post_view from anon;
revoke execute on function shell_can_post(text, text) from anon;
